// Workspace name save/clear: pending local label, exact retry and current admin authority.
const assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path'),http=require('node:http');
const {execFileSync}=require('node:child_process'),{chromium}=require(process.env.AGENTNET_PLAYWRIGHT);
const web=path.resolve(__dirname,'../web'),work=fs.mkdtempSync(path.join(os.tmpdir(),'agentnet-workspace-name-'));
const entry=`
import React from 'react';import {createRoot} from 'react-dom/client';
import {Store,useStore} from './src/store';import {StoreContext} from './src/context';import {OwnedContext} from './src/owned';import {WorkspacesSection} from './src/features/Settings.system';import {useWorkspaceLabel} from './src/features/WorkspaceSwitcher';
const root=document.getElementById('root'),app=document.getElementById('app'),portals=document.getElementById('portals');
const overview={seq:1,version:'fixture',me:{address:'self/laptop',fingerprint:'fixture-key'},person:{person:'self',label:'Alice'},workspace:{name:'Original workspace',server:'fixture.example'},people:[],dms:[],threads:[],needs_you:[]};
const f=window.fixture={writes:[],reads:[],holdReads:false,canRename:true,overview};
const host={platform:'daemon',workspace:{id:'workspace-name',name:'',hub_name:'Old cached name',state:'enrolled',endpoint:'https://fixture.example'},listen(){return()=>{}},async api(p,b){
 if(p.startsWith('/api/overview')){const snapshot=structuredClone(overview);if(f.holdReads)await new Promise(resolve=>f.reads.push(resolve));return snapshot;}
 if(p==='/api/workspace'){const snapshot={...overview.workspace,can_rename:f.canRename};if(f.holdReads)await new Promise(resolve=>f.reads.push(resolve));return snapshot;}
 if(p==='/api/workspace/name')return new Promise((resolve,reject)=>f.writes.push({b:structuredClone(b),resolve,reject}));
 if(p.startsWith('/api/agents'))return {agents:[]};return {};
}};
const store=new Store(host);f.store=store;
f.finish=(i,fail=false,commit=!fail)=>{const w=f.writes[i],value={name:w.b.name,server:'fixture.example',can_rename:f.canRename};if(commit){overview.workspace={name:value.name,server:value.server};overview.seq++}if(fail)w.reject(Error('Invented workspace refusal'));else w.resolve(value)};
f.newer=async(name,person='self')=>{overview.workspace={...overview.workspace,name};overview.person={...overview.person,person};overview.seq++;await store.refetch()};
f.release=()=>{f.holdReads=false;for(const resolve of f.reads.splice(0))resolve()};
function App(){const s=useStore(store,s=>s),label=useWorkspaceLabel();return <><button onClick={()=>store.showTab(s.tab==='settings'?'chats':'settings')}>Toggle view</button><output aria-label="Shared workspace name">{label()}</output>
 {s.tab==='settings'?<WorkspacesSection/>:<p>Another view</p>}<textarea aria-label="Unrelated draft"/></>}
await store.start();store.showTab('settings');createRoot(app).render(<OwnedContext.Provider value={{root,app,portals}}><StoreContext.Provider value={store}><App/></StoreContext.Provider></OwnedContext.Provider>);
`;
const aliases={'optimistic.mjs':'static/optimistic.mjs','pictures.mjs':'static/pictures.mjs','person-topics.mjs':'skins/shared/person-topics.mjs','reaction-preferences.mjs':'skins/shared/reaction-preferences.mjs','collective-mentions.mjs':'skins/shared/collective-mentions.mjs','drive-space.mjs':'skins/shared/drivespace.mjs','drive-setup.mjs':'skins/shared/drivespace-setup.mjs'};
fs.cpSync(path.join(web,'src'),path.join(work,'src'),{recursive:true});
if(process.env.AGENTNET_WORKSPACE_NAME_SOURCE)fs.copyFileSync(process.env.AGENTNET_WORKSPACE_NAME_SOURCE,path.join(work,'src/features/Settings.system.tsx'));
for(const [a,b] of Object.entries(aliases))fs.copyFileSync(path.resolve(web,'../',b),path.join(work,'src',a));
fs.symlinkSync(path.join(web,'node_modules'),path.join(work,'node_modules'),'dir');
const js=require(path.join(web,'node_modules/esbuild')).buildSync({stdin:{contents:entry,resolveDir:work,loader:'tsx'},bundle:true,format:'esm',target:'es2022',jsx:'automatic',define:{'process.env.NODE_ENV':'"production"'},write:false}).outputFiles[0].text;
execFileSync(process.execPath,[path.join(web,'node_modules/@tailwindcss/cli/dist/index.mjs'),'-i',path.join(work,'src/styles.css'),'-o',path.join(work,'style.css'),'--minify'],{cwd:work,stdio:'pipe'});
const css=fs.readFileSync(path.join(work,'style.css'));
const server=http.createServer((req,res)=>{if(req.url==='/entry.mjs'){res.setHeader('Content-Type','text/javascript');return res.end(js)}if(req.url==='/style.css'){res.setHeader('Content-Type','text/css');return res.end(css)}res.setHeader('Content-Type','text/html');res.end('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Workspace name fixture</title><link rel="icon" href="data:,"><link rel="stylesheet" href="/style.css"><div id="root" class="an-root"><div id="app" class="an-app"></div><div id="portals"></div></div><script type="module" src="/entry.mjs"></script>')});
(async()=>{let browser;const reports=[];try{
 await new Promise(r=>server.listen(0,'127.0.0.1',r));browser=await chromium.launch({headless:true});
 const setup=async(width)=>{const page=await browser.newPage({viewport:{width,height:900}});page.setDefaultTimeout(5000);await page.goto('http://127.0.0.1:'+server.address().port);await page.getByLabel('Name for everyone',{exact:true}).waitFor();return page};
 const pending=page=>page.getByRole('region',{name:'Workspace name change',exact:true}),shared=page=>page.getByRole('status',{name:'Shared workspace name',exact:true});
 const save=async(page,name)=>{if(name)await page.getByLabel('Name for everyone',{exact:true}).fill(name);const button=page.getByRole('button',{name:name?'Save for everyone':'Clear',exact:true});await button.evaluate(b=>b.addEventListener('click',e=>fixture.input={at:performance.now(),trusted:e.isTrusted},{once:true,capture:true}));await button.click();await pending(page).waitFor({timeout:500})};
 const capture=async(page,name)=>{if(process.env.AGENTNET_WORKSPACE_NAME_EVIDENCE)await page.screenshot({path:process.env.AGENTNET_WORKSPACE_NAME_EVIDENCE+'-'+name+'.png',fullPage:true})};
 for(const width of [1440,390])for(const action of ['save','clear']){
  const page=await setup(width),errors=[];page.on('pageerror',e=>errors.push(String(e)));const name=action==='save'?'Requested workspace':'';await save(page,name);
  const timing=await page.evaluate(async()=>{await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));return {...fixture.input,feedbackMs:performance.now()-fixture.input.at}});assert(timing.trusted&&timing.feedbackMs<500,JSON.stringify(timing));
  assert(await pending(page).evaluate(el=>{const r=el.getBoundingClientRect();return r.top>=0&&r.bottom<=innerHeight&&r.left>=0&&r.right<=innerWidth}));assert.equal(await page.getByLabel('Name for everyone',{exact:true}).count(),0);assert.equal(await shared(page).textContent(),name||'fixture.example');assert.equal(await page.evaluate(()=>fixture.overview.workspace.name),'Original workspace');assert.equal(await page.evaluate(()=>fixture.store.hasUnsent()),true);
  assert.equal(await page.evaluate(name=>{const a=fixture.store.api.renameWorkspaceForEveryone(name),b=fixture.store.api.renameWorkspaceForEveryone(name);a.catch(()=>{});b.catch(()=>{});return a===b},name),true);assert.equal(await page.evaluate(()=>fixture.writes.length),1);await capture(page,action+'-pending-'+width);
  await page.getByRole('button',{name:'Toggle view',exact:true}).click();await page.getByText('Another view',{exact:true}).waitFor();await page.getByLabel('Unrelated draft').fill('Keep unrelated input');await page.evaluate(()=>fixture.newer('Newer workspace'));assert.equal(await shared(page).textContent(),'Newer workspace');await page.evaluate(()=>fixture.finish(0,true));await page.waitForFunction(()=>fixture.store.get().toasts.some(t=>t.text.includes('Workspace name change not confirmed')));await page.getByRole('button',{name:'Toggle view',exact:true}).click();await pending(page).getByRole('alert').waitFor();assert.equal(await shared(page).textContent(),'Newer workspace');await capture(page,action+'-error-'+width);
  await pending(page).getByRole('button',{name:'Edit workspace name',exact:true}).click();assert.equal(await page.getByLabel('Name for everyone',{exact:true}).inputValue(),name);await save(page,name);await page.evaluate(()=>fixture.finish(1,true));await pending(page).getByRole('alert').waitFor();await pending(page).getByRole('button',{name:'Retry workspace name',exact:true}).click();await page.waitForFunction(()=>fixture.writes.length===3);assert.deepEqual(await page.evaluate(()=>fixture.writes.map(w=>w.b)),Array(3).fill({name}));
  await page.evaluate(()=>{fixture.holdReads=true;fixture.finish(2)});await page.getByText('Name saved; checking current workspace',{exact:true}).waitFor();await capture(page,action+'-checking-'+width);await page.evaluate(name=>fixture.store.api.renameWorkspaceForEveryone(name),name);assert.equal(await page.evaluate(()=>fixture.writes.length),3);await page.evaluate(()=>fixture.release());await pending(page).waitFor({state:'hidden'});assert.equal(await shared(page).textContent(),name||'fixture.example');assert.equal(await page.getByLabel('Name for everyone',{exact:true}).inputValue(),name);
  await page.getByLabel('Name for everyone',{exact:true}).fill('Newer unsaved name');await page.evaluate(()=>fixture.newer('Another linked name'));assert.equal(await page.getByLabel('Name for everyone',{exact:true}).inputValue(),'Newer unsaved name');assert.equal(await page.getByLabel('Unrelated draft').inputValue(),'Keep unrelated input');assert.deepEqual(errors,[]);reports.push({width,action,feedbackMs:timing.feedbackMs});await page.close();
 }
 for(const mode of ['stopped','before-admission','lost-reply','changed-owner','permission-lost','check-only']){
  const page=await setup(390);
  if(mode==='before-admission'){assert.equal(await page.evaluate(async()=>{const work=fixture.store.api.renameWorkspaceForEveryone('Not admitted');fixture.store.stop();await work.catch(()=>{});return fixture.writes.length}),0)}
  else{await save(page,'Captured name');if(mode==='stopped'){assert.equal(await page.evaluate(async()=>{fixture.store.stop();const s=fixture.store.get();fixture.finish(0,false,false);await new Promise(r=>setTimeout(r,35));return fixture.store.get()===s}),true)}else if(mode==='lost-reply'){await page.evaluate(()=>fixture.finish(0,true,true));await pending(page).waitFor({state:'hidden'});assert.equal(await shared(page).textContent(),'Captured name');assert.equal(await page.evaluate(()=>fixture.writes.length),1)}else if(mode==='changed-owner'){await page.evaluate(()=>fixture.newer('Other owner workspace','other'));await pending(page).waitFor({state:'hidden'});await page.evaluate(()=>fixture.finish(0,false,false));await page.waitForTimeout(35);assert.equal(await shared(page).textContent(),'Other owner workspace');assert.equal(await page.getByLabel('Name for everyone',{exact:true}).inputValue(),'Other owner workspace')}else if(mode==='permission-lost'){await page.evaluate(()=>{fixture.canRename=false;fixture.finish(0,true)});await pending(page).getByRole('alert').waitFor();await page.waitForFunction(()=>fixture.store.get().workspaceRename?.error);await page.getByRole('button',{name:'Check workspace name',exact:true}).click();await page.getByRole('button',{name:'Check workspace name',exact:true}).waitFor();assert.equal(await pending(page).getByRole('button',{name:'Retry workspace name',exact:true}).isDisabled(),true);await page.getByRole('button',{name:'Edit workspace name',exact:true}).click();await pending(page).waitFor({state:'hidden'});assert.equal(await page.getByRole('button',{name:'Save for everyone',exact:true}).count(),0);assert.equal(await page.evaluate(()=>fixture.writes.length),1)}else{await page.evaluate(()=>fixture.finish(0,true));await pending(page).getByRole('alert').waitFor();await page.evaluate(()=>{fixture.holdReads=true});await pending(page).getByRole('button',{name:'Check workspace name',exact:true}).click();await page.getByRole('button',{name:'Checking workspace name…',exact:true}).waitFor();assert.equal(await page.evaluate(()=>fixture.writes.length),1);await page.evaluate(()=>fixture.release());await page.getByRole('button',{name:'Check workspace name',exact:true}).waitFor();assert.equal(await page.evaluate(()=>fixture.writes.length),1)}}
  await page.close();
 }
 console.log(JSON.stringify({ok:true,reports,scope:'actual WorkspacesSection and Store; trusted save/clear, held/refused writes, newer name/draft, remount, exact retry, cached-name clearing, status without writes, lost response, permission loss, owner and stopped workspace; synthetic host'}));
 }finally{await browser?.close();await new Promise(r=>server.close(r));fs.rmSync(work,{recursive:true,force:true})}
})().catch(e=>{console.error(e.stack);process.exitCode=1;});
